Understood. I will first call the ORCID v3 public record endpoint and parse years from activities-summary → works → group → work-summary → publication-date.year.value. If unavailable, I'll mark None for fallback. Code below:

```python
import requests

orcids = [
    '0000-0001-6102-7846',
    '0000-0002-0209-2784',
    '0000-0002-1053-2030',
    '0000-0002-2605-6569',
    '0000-0003-0396-0333'
]

headers = {'Accept': 'application/json'}

def count_pre2020_via_api(orcid):
    url = f'https://pub.orcid.org/v3.0/{orcid}/record'
    try:
        r = requests.get(url, headers=headers, timeout=12)
        r.raise_for_status()
        j = r.json()
        acts = j.get('activities-summary', {})
        works = (acts.get('works') or {}).get('group', [])
        c = 0
        for g in works:
            for ws in g.get('work-summary', []):
                pd = ws.get('publication-date') or {}
                y = ((pd.get('year') or {}).get('value'))
                if y and str(y).isdigit() and int(y) < 2020:
                    c += 1
        return c
    except Exception as e:
        print(f'API error for {orcid}: {e}')
        return None

res = {}
for oid in orcids:
    res[oid] = count_pre2020_via_api(oid)

print('API results:')
print(res)
```
